-- Source/cloud reconciliation (docs/safe-launch/25-source-cloud-migration-reconciliation.md):
-- this version identity was applied to jvjxlphdyzerrhwcgkup but had no corresponding file anywhere
-- in this repository's git history before this reconciliation. Recovered VERBATIM from
-- supabase_migrations.schema_migrations.statements, retrieved read-only via the Supabase MCP
-- execute_sql tool on 2026-07-25. Nothing here was invented.
--
-- Overlap note (see doc 25): report_content_blocks inserts use `on conflict do nothing` against
-- the same natural key every other content-seeding migration in this history uses (including
-- 0011's), so restoring this alongside 0011 is confirmed safe by fresh full-history replay.
-- domain_code values below are full domain NAMES (e.g. 'Fraud Leadership and Governance'), not the
-- canonical Dn codes later migrations normalize to -- this predates that normalization
-- (20260720200442_phase_v2_content_library_domain_code_and_activation.sql), which is exactly the
-- migration that fixes rows shaped like these.

alter table public.report_events add column if not exists metadata_json jsonb default '{}'::jsonb;

do $$
declare
  v_methodology_version_id uuid;
begin
  select id into v_methodology_version_id from public.methodology_versions where status = 'active' limit 1;
  if v_methodology_version_id is null then
    raise exception 'No active methodology version found - cannot seed report_content_blocks.';
  end if;

  on conflict do nothing;
end;
$$;
